export function useServer(
  id: string,
  { poll = true }: UseServerOptions = {},
): UseServerResult {
  const { data, loading, error, refetch, startPolling, stopPolling } = useQuery(
    ServerDocument,
    {
      variables: { id },
      fetchPolicy: "cache-first",
      errorPolicy: "all",
      skipPollAttempt: skipPollWhenHidden,
    },
  );

  const service = useMemo(
    () => (data?.server ? toServiceView(data.server) : null),
    [data],
  );

  // Not yet loaded counts as converging, matching useDatabase: an App whose
  // first read is still in flight is exactly the one whose phase is about to
  // move.
  useConvergingPoll(
    startPolling,
    stopPolling,
    service ? isConvergingPhase(service) : true,
    poll,
  );

  const refetchViews = useCallback(async () => {
    const res = await refetch();
    return res.data?.server ? [toServiceView(res.data.server)] : [];
  }, [refetch]);

  return { service, loading, error, refetch: refetchViews };

export const RESOURCE_POLL_INTERVAL_MS = 30_000;

/**
 * Fast cadence for a resource that is still converging (a provisioning
 * database, an upgrading key-value store): poll at this interval until the
 * status settles, then fall back to `RESOURCE_POLL_INTERVAL_MS`.
 */
export const CONVERGING_POLL_INTERVAL_MS = 3_000;

export function useConvergingPoll(
  startPolling: (intervalMs: number) => void,
  stopPolling: () => void,
  converging: boolean,
  enabled = true,
): void {
  useEffect(() => {
    if (!enabled) return;
    startPolling(
      converging ? CONVERGING_POLL_INTERVAL_MS : RESOURCE_POLL_INTERVAL_MS,
    );
    return () => stopPolling();
  }, [enabled, converging, startPolling, stopPolling]);

